INSERT INTO `areas` (`id_area`, `nombre_area`, `descripcion_a`) VALUES
(1, 'Recepción y logística', 'Traslado de materias primas, componentes y piezas entre estaciones'),
(2, 'Estampado y conformado', 'Conformado y corte de láminas y piezas metálicas'),
(3, 'Carrocería y soldadura', 'Unión, sujeción y manipulación de piezas de la carrocería'),
(4, 'Pintura y tratamiento', 'Aplicación, ventilación y curado del recubrimiento'),
(5, 'Ensamblaje', 'Posicionamiento, atornillado e inserción de componentes'),
(6, 'Motor / sistemas y pruebas', 'Montaje del tren motriz, inspección y pruebas finales');
INSERT INTO `catalogo_sensores` (`id_catalogo`, `nombre_sensor`, `tipo_dato`, `caracteristicas`, `utilidad`) VALUES
(1, 'Termocupla / RTD (Pt100)', 'Numérico Analógico (°C / °F)', 'Alta precisión térmica, rango amplio (-50 °C a 600 °C), salida de 4-20 mA o Modbus RTU.', 'Monitorea la temperatura de motores, aceite hidráulico, paquetes de baterías y hornos de curado para prevenir sobrecalentamientos.'),
(2, 'Transductor de Corriente (TC) / Shunt', 'Numérico Analógico (Amperios - A)', 'Medición no invasiva mediante efecto Hall o pinza inductiva, respuesta instantánea.', 'Mide consumo eléctrico, evalúa sobrecargas en motores/servomotores y monitorea la estabilidad en procesos de soldadura.'),
(3, 'Transductor de Presión (Hidráulico/Neumático)', 'Numérico Analógico (bar / PSI / kPa)', 'Célula piezorresistiva en acero inoxidable, salida de 4-20 mA o interfaz IO-Link.', 'Evalúa la compresión en prensas, la fuerza de elevación en montacargas y las fugas en redes neumáticas de sujeción.'),
(4, 'Acelerómetro de Vibración (Piezoeléctrico)', 'Numérico Continuo (Vibración RMS - mm/s, g)', 'Medición axial o triaxial de alta frecuencia, carcasa industrial resistente a ambientes agresivos.', 'Base del mantenimiento predictivo: detecta desgaste en rodamientos, desbalanceo de rodillos, holguras y fallas en husillos/engranajes.'),
(5, 'Encoder Incremental / Absoluto', 'Numérico Digital / Pulsos (RPM, Grados °)', 'Alta resolución por vuelta (pulsos/rev), comunicación EnDat, SSI o PROFINET.', 'Controla la velocidad de bandas transportadoras, mide la posición angular del cigüeñal en prensas y la odometría/rutas en AGVs.'),
(6, 'Scanner LiDAR (2D/3D)', 'Matriz de Datos / Distancia (m, mm)', 'Tecnología Time-of-Flight (ToF), campo de visión de 180° a 360°, interfaz Ethernet TCP/IP.', 'Permite la navegación autónoma en vehículos AGV, el mapeo de áreas en tiempo real y la prevención de colisiones.'),
(7, 'Celda de Carga / Galga Extensométrica', 'Numérico Analógico (Fuerza en kN / Toneladas)', 'Deformación piezoeléctrica/extensométrica de alta rigidez, respuesta dinámica rápida.', 'Mide la fuerza de impacto en troquelado/prensado mecánico y el esfuerzo de inserción durante el ensamblaje.'),
(8, 'Sensor Fotoeléctrico / Proximidad Inductivo', 'Booleano (Digital 1 / 0 - ON/OFF)', 'Detección óptica u electromagnética sin contacto, tiempos de respuesta sub-milisegundo.', 'Conteo de piezas en transportadores, verificación de presencia de componentes y confirmación de cierre en sistemas clamp.'),
(9, 'Regla Óptica / Sensor Lineal (LVDT)', 'Numérico Analógico (Distancia en mm)', 'Medición de precisión milimétrica o micrométrica, salida SSI, 0-10V o 4-20 mA.', 'Monitorea el recorrido del cilindro en prensas hidráulicas y mide la profundidad de inserción de bujes o piezas.'),
(10, 'Transductor de Torque Dinámico', 'Numérico Analógico (Torque en N·m)', 'Diseñado para ejes giratorios en herramientas de apriete, alta tasa de muestreo.', 'Controla y calibra la precisión de apriete en atornilladores automáticos para evitar uniones sueltas o roscas barridas.'),
(11, 'Cámara de Visión Artificial (Matricial/3D)', 'Matriz de Imagen / Coordenadas (Píxeles, mm)', 'Sensor CMOS de alta resolución, iluminador integrado, interfaz GigE / EtherNet-IP.', 'Control de calidad al 100%, detección de defectos de pintura/superficie, verificación dimensional y guía de robots.'),
(12, 'Presostato Diferencial / Anemómetro', 'Numérico Analógico (ΔP en Pa, Flujo en m/s)', 'Sensibilidad para rangos bajos de presión de aire y gases, salida de 4-20 mA.', 'Alerta sobre la saturación de filtros en cabinas de pintura y verifica el flujo laminar de aire en ventiladores y hornos.');
INSERT INTO `dispositivos_sensor` (`id_dispositivo`, `id_maquina`, `id_catalogo`, `codigo`, `nombre_sensor`, `marca_modelo`, `tipo_salida`, `variable_medida`, `tipo_dato_origen`, `formato_transmision`, `aplicacion_mantenimiento`, `lectura_software`, `activo`) VALUES
(1, 1, NULL, 'EQ-LOG-01-S1', 'Sensor de presencia del operador (OPS)', NULL, NULL, '(Asiento vacío / Sin operador) 1Fuerza / Presión mecánica en el asiento (Masa del operador).', 'BOOL (Booleano: 0 / 1 o False / True).', 'Entrada Digital (DI) a PLC / Registro de bit en trama CANbus (Ej. ID 0x0CF00400).', 'Preventivo: Bloqueo inmediato de la tracción y sistema hidráulico si el operador abandona la cabina. Predictivo: Registro de horas reales de operación efectiva vs. tiempo en ralentí para mantenimiento.', 'Lo que genera el sensor: Un cambio de voltaje (ejemplo: 0V sin operador, 24V con operador). El módulo receptor lee el pin de entrada digital. En el software verás: Un estado lógico o bandera (TRUE / FALSE). En la pantalla se representa como un indicador de color (Verde = Operador presente / Rojo = Cabina vacía). El software lee el bit de entrada. Si operador_presente == False, ejecuta la rutina de interrupción de motor/hidráulico, activa un flag de alerta en el Dashboard y guarda el evento de desconexión con timestamp.', 1),
(2, 1, 3, 'EQ-LOG-01-S2', 'Sensor de carga e inclinación/velocidad del mástil', NULL, NULL, 'Presión hidráulica en el cilindro de elevación (convertida a kilogramos/libras). • Presión/Carga: 0 a 250 bar (0 a 3000 kg) • Altura: 0 a 6000 mm (0 a 6 metros) • Ángulo de inclinación: -5° a +12° Altura de elevación del mástil (metros / milímetros).', 'FLOAT / REAL (Punto flotante de 32 bits, tras la fórmula de escalado).', 'Analógico (4-20 mA o 0-10 V) o Bus Industrial (CANbus / Modbus)', 'Preventivo: Alerta de sobrecarga y reducción automática de velocidad a gran altura. Predictivo: Análisis de fatiga de materiales por ciclos de carga acumulados para predecir fallas hidráulicas..', 'El software recibe la trama analógica/digital, aplica la fórmula de escalado (Carga (kg) = f(mA)), actualiza el valor en pantalla (peso_carga_kg = 1850.5) y evalúa si supera los umbrales de seguridad programados (IF carga > limite THEN reducir_velocidad()).', 1),
(3, 1, NULL, 'EQ-LOG-01-S3', 'Sensor de dirección y reducción automática en curvas', NULL, NULL, 'Posición y ángulo rotacional de las ruedas traseras/columna de dirección.', 'INT16 (Entero signado para el ángulo: -90° a +90°) y FLOAT (para velocidad en km/h).', 'Contador de alta velocidad (HSC) en PLC o trama CANopen / J1939.', 'Preventivo: Desaceleración automática al tomar curvas cerradas para evitar volcaduras laterales. Predictivo: Detección de desgaste irregular en llantas o desalineación por patrón de giros.', 'El software contabiliza los impulsos o lee el registro de ángulo, calcula los grados reales (angulo_giro_deg = -35.0), evalúa la velocidad actual y, si detecta riesgo de volcadura, envía una orden de limitación al controlador del motor.', 1),
(4, 2, 6, 'EQ-LOG-02-S1', 'Escáner láser de seguridad LiDAR', NULL, NULL, 'Distancia, posición angular y velocidad de aproximación de objetos en 360°', 'ARRAY / STRUCT (Matriz de distancias x, y en mm) y FLOAT (Distancia mínima en metros).', 'Pulso de luz infrarroja / Conexión de red de seguridad Ethernet Industrial (100 Mbps). Trama de datos en bus de seguridad EtherNet/IP CIP Safety o PROFINET Safety.', 'Preventivo: Define dinámicamente zonas de desaceleración (2.5 m) y parada de emergencia (0.6 m).Predictivo: Análisis de rutas con alta frecuencia de peatones o bloqueos no planificados.', 'software procesa la nube de puntos en tiempo real. Si distancia_obstaculo < 2.5m, envía la instrucción de frenado gradual (reducir_velocidad_50%). Si distancia_obstaculo < 0.6m, dispara la interrupción de emergencia E-STOP instantáneamente', 1),
(5, 2, 8, 'EQ-LOG-02-S2', 'Sensor de detección óptica / ultrasonido en puntas de horquilla', NULL, NULL, 'Presencia física de carga, distancia libre hasta la tarima y alineación del estante.', NULL, 'Haz fotoeléctrico reflectivo / Ondas ultrasónicas (0 a 10V DC o comunicación IO-Link). Bus industrial de campo IO-Link o entrada discreta al PLC de seguridad.', 'Preventivo: Bloquea el avance del mástil si la tarima está mal posicionada o destruida, evitando caídas de carga. Predictivo: Monitoreo de precisión de estanterías dañadas o fuera de tolerancia geométrica.', 'El software consulta los dos sensores de las horquillas. Si solo uno detecta material (sensor_izq == True Y sensor_der == False), el software cancela la maniobra por asimetría y notifica al sistema central un error de carga torcida.', 1),
(6, 2, NULL, 'EQ-LOG-02-S3', 'Inclinómetro 3D de chasis y centro de gravedad', NULL, NULL, 'Ángulo de inclinación sobre los ejes y (Nivelación del piso y estabilidad vertical).', 'INT16 (Grados centígrados de inclinación con signo: -180.0° a +180.0°).', 'Variación capacitiva MEMS / Voltaje analógico proporcional de 0.5V a 4.5V. Mensaje codificado en bus CANopen (Protocolo CAN J1939 / ID de trama 0x18FEE600).', 'Preventivo: Limita la velocidad máxima y la elevación máxima del mástil si el suelo presenta irregularidades. Predictivo: Identificación de baches, grietas o desnivelaciones en las pistas del almacén.', 'El software evalúa la inclinación en tiempo real. Si ABS(angulo_chasis) > 2.0 grados mientras altura_elevacion > 4.0 metros, el sistema detiene inmediatamente el movimiento de elevación y emite una alerta de inestabilidad estructural.', 1),
(7, 3, 4, 'EQ-LOG-03-S1', 'Sensor de vibración', NULL, NULL, 'Vibración del motorreductor (mm/s RMS)', 'FLOAT (Velocidad de vibración en mm/s RMS, p. ej. 3.5 mm/s)', 'IO-Link 1.1.3 (COM3) — datos de proceso digitales en formato Record.', 'Permite analizar la tendencia de la vibración del motorreductor para identificar progresivamente desgaste de rodamientos, desalineación, desequilibrio, holguras o problemas en engranajes. Si la vibración aumenta de forma sostenida durante un período determinado', 'El software lee el valor de vibración v-RMS, registra el histórico de mediciones, analiza su tendencia y, si detecta un aumento progresivo por encima del valor establecido (ej. vRMS = 3.2 mm/s), identifica una posible degradación y genera una alerta para programar la revisión del motorreductor.', 1),
(8, 3, 2, 'EQ-LOG-03-S2', 'Transductor de corriente', NULL, NULL, 'Corriente eléctrica consumida por el motorreductor (A).', 'FLOAT — valor decimal de corriente en amperios (A).', 'señal analógica de 4–20 mA.', 'permite monitorear y comparar la corriente de las fases U, V y W a lo largo del tiempo. Un aumento progresivo o un desequilibrio entre fases puede indicar una posible degradación del motor, permitiendo programar una revisión antes de que ocurra una falla.', 'El software recibe la señal analógica de 4–20 mA, aplica el escalado correspondiente para convertirla a corriente en amperios, actualiza el valor de cada fase (corriente_U = 8.5 A) y compara las mediciones U, V y W con sus valores históricos para detectar aumentos o desequilibrios que indiquen una posible degradación del motor.', 1),
(9, 4, 3, 'EQ-EST-04-S1', 'Sensor de presión hidráulica', 'ifm PN7', NULL, 'Presión hidráulica', 'INT16 (Presión actual) + BOOL (OUT1) + BOOL (OUT2)', 'Trama de datos digital cíclica y acíclica mediante protocolo IO-Link hacia Maestro de campo.', 'Prevención: Permite identificar incrementos o picos anormales de presión mediante el seguimiento histórico de la variable y de los valores máximos (Hi), facilitando una inspección del sistema hidráulico antes de que la condición pueda provocar una falla. Detección de Falla: Identifica cambios progresivos o comportamientos anormales en la presión hidráulica mediante el análisis de la variable a lo largo del tiempo, que pueden indicar posibles problemas como fugas, pérdida de rendimiento de la bomba u obstrucciones en el circuito.', 'El software lee el estado de la entrada digital (DI) del PLC conectada al contacto de relé del Touchswitch. El estado de la entrada representa una condición normal o de alarma; cuando se detecta la condición de alarma, el software registra la anomalía y genera el aviso correspondiente.', 1),
(10, 4, NULL, 'EQ-EST-04-S2', 'Sensor de calidad y condición del aceite hidráulico', NULL, NULL, 'Constante dieléctrica del aceite, porcentaje de contenido de humedad (agua en ppm) y temperatura (°C).', 'FLOAT (Constante dieléctrica del aceite) + FLOAT (Contenido de agua en ppm) + INT16 (Temperatura del aceite en °C)', 'Protocolo industrial digital (Modbus TCP, IO-Link o CANbus).', 'Prevención: Permite identificar cambios anormales en la calidad del aceite hidráulico que pueden favorecer el desgaste, la oxidación y problemas de funcionamiento en bombas y válvulas. Detección de Falla: Detecta cambios en la condición del aceite, como aumento del contenido de agua y variaciones de la constante dieléctrica, que pueden indicar contaminación o degradación del fluido.', 'El software lee los registros del bus de comunicación, mapea las variables en el sistema (constante_dieletrica_aceite, contenido_agua_ppm y temperatura_aceite_c) y las registra en una base de datos cronológica. El programa evalúa continuamente el estado del fluido comparando las lecturas con los parámetros de referencia establecidos, aplicando reglas algorítmicas (IF contenido_agua_ppm > umbral_critico THEN generar_alerta_condicion_aceite()) para identificar contaminación por agua y posibles condiciones de degradación del aceite.', 1),
(11, 4, 9, 'EQ-EST-04-S3', 'Sensor de posición lineal magnetostrictivo para cilindros hidráulicos', NULL, NULL, 'Posición absoluta del vástago, velocidad de carrera del cilindro y tiempo total por ciclo de prensado.', 'FLOAT (Posición exacta del vástago del cilindro en mm) + FLOAT (Velocidad de desplazamiento calculada en mm/s)', 'Señal analógica de 4–20 mA o trama digital mediante interfaces/buses industriales como PROFINET, EtherCAT, SSI, CANopen o IO-Link, según el modelo y la interfaz disponible.', 'Detección de Falla: Identifica desviaciones anormales en la posición y velocidad de desplazamiento del cilindro que pueden indicar desgaste, atascamiento, pérdida de presión o problemas en los sellos internos. Predictivo: Analiza las variaciones de velocidad y posición durante ciclos de operación para identificar tendencias de degradación, desgaste o cambios en el comportamiento del cilindro que puedan requerir mantenimiento antes de una falla.', 'El software recibe la señal de posición del sensor, aplica el escalado correspondiente para convertirla a milímetros y actualiza el valor en pantalla (posicion_piston_mm = 320.5). NOVA calcula la velocidad de desplazamiento y el tiempo de carrera a partir de las lecturas sucesivas de posición. El algoritmo compara estos valores con el perfil de funcionamiento establecido (IF tiempo_carrera > limite_patron THEN generar_alerta_anomalia_cilindro()) para identificar posibles anomalías asociadas con desgaste, pérdida de presión, problemas en los sellos o desalineación mecánica.', 1),
(12, 5, 7, 'EQ-EST-05-S1', 'Sensor de esfuerzo/deformación estructural (célula de carga extensométrica)', NULL, NULL, 'Fuerza aplicada por la prensa (kN o toneladas) y deformación estructural del bastidor (µε), según el tipo de sensor instalado.', 'FLOAT (Fuerza aplicada por la prensa en kN o toneladas) + FLOAT (Deformación estructural del bastidor en µε)', 'Señal analógica acondicionada mediante amplificador/transmisor y conversión a señal digital para integración con sistemas de control mediante interfaces industriales como PROFINET, EtherCAT o CANopen, según el equipo utilizado.', 'Detección de Falla: Detecta valores de fuerza que superan los límites establecidos de operación, generando una alerta ante posibles sobrecargas que puedan afectar el bastidor, el cigüeñal o los troqueles. Predictivo: Analiza la tendencia de la firma de fuerza (curva fuerza-tiempo) durante los ciclos de operación para identificar cambios progresivos que puedan indicar desgaste de herramientas, desalineación de la matriz o degradación de componentes mecánicos de la prensa.', 'El software recibe los datos de deformación del bastidor, aplica el factor de calibración correspondiente para calcular la fuerza aplicada y actualiza el valor en pantalla (fuerza_golpe_ton = 125.8). NOVA registra la curva de fuerza durante cada carrera y compara su comportamiento con los parámetros de referencia establecidos. El algoritmo analiza continuamente la magnitud y repetibilidad de la fuerza (IF desviacion_fuerza > limite_permitido THEN generar_alerta_anomalia_prensa()) para identificar cambios anormales que puedan estar relacionados con desgaste del troquel, desalineación de la corredera o degradación de componentes mecánicos.', 1),
(13, 5, 4, 'EQ-EST-05-S2', 'Sensor de vibración e impacto triaxial con análisis de frecuencia', NULL, NULL, 'Aceleración de vibración (g), velocidad de vibración RMS (mm/s), factor de cresta para detección de impactos y temperatura del punto de medición (°C).', 'FLOAT (Velocidad de vibración RMS en mm/s) + FLOAT (Aceleración de impacto en g) + FLOAT (Factor de cresta) + INT16 (Temperatura del punto de medición en °C)', 'Trama digital de alta velocidad mediante interfaces industriales como IO-Link, PROFINET o EtherNet/IP, según el modelo y la interfaz de comunicación utilizada', 'Detección de Falla: Identifica valores anormales de temperatura, vibración o impactos que pueden indicar condiciones como falta de lubricación, sobrecalentamiento, holguras mecánicas o deterioro de componentes del sistema de transmisión. Predictivo: Analiza el espectro de frecuencias (FFT), junto con las tendencias de vibración y temperatura, para identificar patrones compatibles con desgaste de rodamientos, holguras mecánicas o desbalanceo en elementos rotativos como el volante de inercia.', 'Cómo lee el Software cada sensor específico: El software recibe los datos de vibración y temperatura, procesa las señales y actualiza los valores en pantalla (vibracion_rms_mms = 4.2 y temperatura_punto_c = 65.0). NOVA registra las mediciones y, cuando dispone de datos espectrales, analiza las frecuencias características de la vibración y las compara con los parámetros de referencia establecidos para la máquina. El algoritmo realiza un seguimiento histórico de la vibración RMS, el factor de cresta y la temperatura (IF vibracion_rms_mms > limite_alerta THEN generar_alerta_anomalia_vibracion()) para identificar cambios anormales que puedan estar relacionados con desgaste de rodamientos, holguras, desbalanceo u otras condiciones mecánicas que requieran inspección.', 1),
(14, 5, NULL, 'EQ-EST-05-S3', 'Sensor de temperatura infrarrojo sin contacto', NULL, NULL, 'Temperatura superficial de los discos y superficies de fricción del embrague y freno de la prensa (°C o °F).', 'FLOAT (Temperatura superficial medida en °C)', 'Señal analógica estándar de 4–20 mA o comunicación digital mediante IO-Link o Modbus RTU, según el modelo del sensor.', 'Detección de Falla: Identifica temperaturas superficiales anormalmente elevadas en los discos y superficies de fricción del embrague y freno, generando una alerta ante posibles condiciones de sobrecalentamiento, deslizamiento o problemas de frenado. Predictivo: Analiza la tendencia de temperatura durante los ciclos de operación para detectar incrementos progresivos o cambios anormales en el comportamiento térmico que puedan estar relacionados con desgaste de las superficies de fricción o problemas en el sistema de embrague y freno.', 'El software recibe la señal de temperatura infrarroja y aplica el factor de emisividad configurado para convertir la medición en grados Celsius, actualizando el valor en pantalla (temperatura_freno_c = 85.3). NOVA registra el histórico de temperatura durante los ciclos de operación y compara las mediciones con los parámetros de referencia establecidos para el sistema de embrague y freno. El algoritmo analiza continuamente la temperatura y su tendencia (IF temperatura_freno_c > limite_temperatura THEN generar_alerta_anomalia_termica()) para identificar condiciones anormales de calentamiento que puedan requerir inspección del sistema de frenado y de las superficies de fricción.', 1),
(15, 6, 4, 'EQ-EST-06-S1', 'Sensor de vibración y aceleración industrial de alta frecuencia', NULL, NULL, 'Velocidad de vibración eficaz (RMS en mm/s), aceleración pico (g), factor de cresta para detectar impactos y temperatura del punto de medición (°C).', 'FLOAT (Velocidad de vibración RMS en mm/s) + FLOAT (Aceleración pico en g) + FLOAT (Factor de cresta) + INT16 (Temperatura del punto de medición en °C)', 'Trama de datos digital mediante IO-Link. El sensor se conecta a un maestro IO-Link, que puede transmitir los datos hacia el sistema de control mediante PROFINET o EtherNet/IP, según el maestro utilizado.', 'Detección de Falla: Detecta incrementos anormales de vibración, impactos o aceleración que pueden indicar una colisión, rotura de herramienta, desbalanceo u otra condición anormal del husillo o de los elementos mecánicos. La condición detectada puede generar una alarma o activar una parada del proceso mediante el sistema de control. Predictivo: Analiza las tendencias de vibración y, cuando se dispone de datos de forma de onda o espectro, analiza sus componentes de frecuencia (FFT) para identificar cambios progresivos compatibles con holguras mecánicas, desbalanceo, desgaste de rodamientos o deterioro de otros componentes del husillo.', 'El software recibe los datos digitales de vibración y temperatura mediante IO-Link, procesa los indicadores de vibración y, cuando se dispone de datos de forma de onda o espectro, puede realizar análisis en el dominio del tiempo y la frecuencia. Los valores se actualizan en la interfaz (vibracion_husillo_rms = 1.8 y temperatura_punto_c = 42.5). NOVA registra las mediciones durante los ciclos de mecanizado y compara las tendencias con parámetros de referencia establecidos para la máquina y el punto de medición. El algoritmo puede aplicar una condición lógica (IF vibracion_husillo_rms > limite_referencia THEN generar_alerta_anomalia_husillo()) para detectar cambios anormales compatibles con desgaste, desbalanceo, holguras o deterioro de componentes del husillo que requieran inspección.', 1),
(16, 6, 2, 'EQ-EST-06-S2', 'Sensor de corriente de efecto Hall para monitoreo de carga de motores', NULL, NULL, 'Corriente eléctrica instantánea del motor o servomotor (A). El consumo de energía y la carga eléctrica pueden ser calculados por el software a partir de la corriente medida y otros parámetros eléctricos.', 'FLOAT (Corriente eléctrica RMS del motor en A) o UINT16 (Valor de corriente escalado), según la interfaz y el modelo del sensor.', 'Señal analógica de corriente de 4–20 mA o salida digital mediante IO-Link, Modbus RTU o PROFINET, según el modelo y la interfaz de comunicación utilizada.', 'Detección de Falla: Detecta incrementos anormales de corriente en el motor o servomotor que pueden indicar sobrecarga, atasco mecánico, incremento de la resistencia al movimiento o una condición anormal durante el mecanizado. La condición detectada puede generar una alarma o activar una parada del movimiento mediante el sistema de control. Predictivo: Analiza la tendencia de la corriente durante condiciones de mecanizado comparables para identificar incrementos progresivos de la carga del motor. Estos cambios pueden ser compatibles con desgaste de la herramienta, aumento de la fricción o deterioro de componentes mecánicos, permitiendo programar una inspección o mantenimiento antes de una falla.', 'El software recibe la señal de corriente del transductor y aplica la escala o factor de conversión correspondiente para obtener el valor de corriente en amperios (corriente_motor_amp = 14.6). Registra las mediciones durante los ciclos de mecanizado y compara los valores con una línea base establecida para condiciones de operación similares. El algoritmo analiza las variaciones y tendencias de la corriente mediante una condición lógica (IF corriente_motor_amp > limite_referencia THEN generar_alerta_sobrecarga_motor()) para detectar incrementos anormales de carga que puedan estar relacionados con desgaste de la herramienta, sobrecarga, aumento de fricción o problemas mecánicos que requieran inspecci', 1),
(17, 6, NULL, 'EQ-EST-06-S3', 'Sensor de flujo de refrigerante con medición de presión integrada', NULL, NULL, 'Caudal volumétrico del fluido refrigerante (L/min) y presión del fluido en la línea de suministro (bar).', 'FLOAT (Caudal volumétrico del refrigerante en L/min) + FLOAT (Presión del fluido en bar).', 'Trama de datos digital mediante IO-Link o señal analógica de 4–20 mA, según el modelo del sensor. Cuando se utiliza un maestro IO-Link, los datos pueden integrarse posteriormente mediante PROFINET u otro protocolo industrial compatible con el maestro.', 'Detección de Falla: Detecta una disminución anormal del caudal o una variación de presión en el circuito de refrigerante que puede indicar obstrucción de las boquillas, restricción en las líneas, saturación del filtro o funcionamiento incorrecto del sistema de refrigeración. La condición detectada puede generar una alarma o activar una acción de protección mediante el sistema de control. Predictivo: Analiza las tendencias de caudal y presión durante los ciclos de mecanizado para identificar disminuciones progresivas del caudal o incrementos anormales de presión que puedan indicar acumulación de suciedad, obstrucción progresiva de las boquillas o saturación del sistema de filtrado, permitiendo programar una inspección antes de que afecte el proceso de corte.', 'El software recibe los datos de caudal y presión mediante la interfaz de comunicación utilizada y los convierte a sus respectivas unidades de medida, actualizando los valores en la interfaz (caudal_refrigerante_lmin = 12.4 y presion_linea_bar = 3.5). Registra el comportamiento del circuito de refrigeración durante los ciclos de mecanizado y compara las lecturas con los parámetros de referencia establecidos para las condiciones de operación. El algoritmo analiza las variaciones y tendencias mediante una condición lógica (IF caudal_refrigerante_lmin < limite_referencia THEN generar_alerta_flujo_refrigerante()) para detectar una disminución anormal del caudal que pueda estar relacionada con obstrucciones, restricciones en las líneas o saturación del sistema de filtrado y requiera una inspección.', 1),
(18, 7, 7, 'EQ-CAR-07-S1', 'Sensor de fuerza piezoeléctrico en la pinza de soldadura', NULL, NULL, 'Fuerza dinámica de compresión ejercida entre los electrodos durante el cierre de la pinza sobre las láminas (kN). El tiempo de estabilización de la fuerza puede ser calculado a partir de la señal registrada.', 'FLOAT (Fuerza dinámica de compresión entre los electrodos en kN) + FLOAT (Tiempo de estabilización de la fuerza en ms).', 'Señal eléctrica acondicionada proveniente del sensor piezoeléctrico hacia un módulo de adquisición o controlador. La señal puede ser digitalizada para su integración mediante EtherCAT, PROFINET u otro bus industrial, según el sistema de adquisición y control utilizado.', 'Detección de Falla: Detecta valores de fuerza de sujeción inferiores o superiores a los parámetros establecidos durante el ciclo de soldadura, lo que puede indicar problemas en el mecanismo de la pinza, pérdida de capacidad de accionamiento, desalineación o condiciones anormales de contacto entre los electrodos y las láminas. La condición detectada puede generar una alarma o impedir el disparo de soldadura mediante el sistema de control. Predictivo: Analiza la tendencia de la fuerza de sujeción durante ciclos de soldadura comparables para identificar pérdidas progresivas o cambios en el comportamiento de la pinza que puedan estar relacionados con desgaste de componentes mecánicos, electrodos o elementos del sistema de accionamiento, permitiendo programar una inspección, ajuste o mantenimiento antes de que afecte la calidad de la soldadura.', 'El software recibe la señal de fuerza proveniente del sistema de medición durante la fase de compresión de la pinza y convierte la señal al valor correspondiente en kN (fuerza_cierre_kn = 3.2). Registra la fuerza alcanzada en cada ciclo de soldadura y compara las mediciones con los parámetros de referencia establecidos para las condiciones de operación. El algoritmo analiza las variaciones y tendencias de la fuerza mediante una condición lógica (IF fuerza_cierre_kn < limite_fuerza_minima THEN generar_alerta_fuerza_pinza()) para detectar una pérdida anormal de fuerza que pueda requerir inspección del mecanismo de la pinza, los electrodos o el sistema de accionamiento', 1),
(19, 7, NULL, 'EQ-CAR-07-S2', 'Sensor de flujo magnético-inductivo con medición de temperatura integrada', NULL, NULL, 'Caudal volumétrico del agua de enfriamiento (L/min) y temperatura de retorno del fluido (°C).', 'FLOAT (Caudal volumétrico del agua de enfriamiento en L/min) + FLOAT (Temperatura del fluido de refrigeración en °C).', 'Trama de datos digital mediante IO-Link o salida analógica, según el modelo del sensor. Cuando se utiliza un maestro IO-Link, los datos pueden integrarse posteriormente mediante PROFINET o EtherNet/IP, según el sistema de control utilizado.', 'Detección de Falla: Detecta caídas o interrupciones del caudal que pueden indicar fugas, obstrucciones o fallas en el circuito de refrigeración. Predictivo: Analiza la tendencia del caudal y temperatura para identificar obstrucciones progresivas o deterioro del sistema antes de afectar la refrigeración.', 'El software recibe los datos de caudal y temperatura, los convierte a sus unidades correspondientes y actualiza los valores (caudal_agua_lmin = 8.5 y temperatura_retorno_c = 34.2). Registra las mediciones durante los ciclos de soldadura y compara sus tendencias con los parámetros de referencia. El algoritmo aplica una condición lógica (IF caudal_agua_lmin < limite_referencia THEN generar_alerta_flujo_refrigeracion()) para detectar posibles obstrucciones o fallas en el circuito de enfriamiento.', 1),
(20, 7, 2, 'EQ-CAR-07-S3', 'Transductor de corriente flexible tipo bobina de Rogowski', NULL, NULL, 'Corriente de soldadura durante los pulsos eléctricos (kA). La duración del pulso de corriente puede ser calculada a partir de la señal registrada (ms).', 'FLOAT (Corriente RMS de soldadura en kA) + UINT16 (Tiempo del pulso calculado en ms)', 'Señal analógica de alta velocidad proveniente de la bobina de Rogowski hacia un integrador o módulo de adquisición. La señal digitalizada puede integrarse posteriormente mediante EtherCAT, PROFINET u otro protocolo industrial, según el sistema de adquisición utilizado.', 'Detección de Falla: Detecta variaciones anormales en la corriente o duración del pulso de soldadura que pueden indicar una condición irregular del proceso. La condición puede generar una alarma y marcar la soldadura para inspección o rechazo mediante el sistema de control. Predictivo: Analiza la tendencia de la corriente de soldadura bajo condiciones comparables para identificar cambios progresivos que puedan indicar degradación del circuito de potencia, conexiones o componentes eléctricos que requieran inspección.', 'El software recibe la señal de alta velocidad de la bobina de Rogowski mediante el sistema de adquisición, procesa la señal para obtener la corriente RMS del pulso y actualiza el valor en pantalla (corriente_soldadura_ka = 9.4). El sistema registra la corriente de cada ciclo y la compara con los parámetros de referencia establecidos para las condiciones de soldadura. El algoritmo analiza las variaciones y tendencias de la corriente (IF corriente_soldadura_ka < limite_referencia THEN generar_alerta_corriente_soldadura()) para identificar cambios anormales que puedan requerir inspección del circuito de potencia o del sistema de soldadura. |', 1),
(21, 8, 7, 'EQ-CAR-08-S1', 'Sensor de fuerza/tensión del sistema de alimentación de alambre', NULL, NULL, 'Fuerza o tensión mecánica de alimentación del alambre de soldadura (N), asociada a la resistencia que presenta el alambre durante su desplazamiento.', 'FLOAT (Fuerza de resistencia mecánica del alambre en N).', 'Señal eléctrica acondicionada del transductor hacia el módulo de adquisición o controlador del sistema de alimentación de alambre. La información digitalizada puede integrarse con el sistema de control mediante EtherCAT, PROFINET o DeviceNet, dependiendo de la arquitectura y del equipo utilizado.', 'Detección de Falla: Detecta un aumento anormal de la fuerza de resistencia durante la alimentación del alambre, que puede indicar un atasco o una restricción en el sistema de alimentación. Predictivo: Analiza la tendencia de la fuerza de resistencia para identificar incrementos progresivos compatibles con desgaste, suciedad u obstrucciones en el sistema de alimentación que requieran mantenimiento.', 'El software recibe la señal digitalizada del transductor, la convierte a fuerza y actualiza el valor (fuerza_alambre_n = 24.5). Registra las mediciones y compara la tendencia con parámetros de referencia. El algoritmo puede aplicar una condición (IF fuerza_alambre_n > limite_referencia THEN generar_alerta_alimentacion()) para detectar un aumento anormal de resistencia que requiera inspección del sistema de alimentación del alambre.', 1),
(22, 8, NULL, 'EQ-CAR-08-S2', 'Sensor de caudal másico térmico para gases con presión integrada', NULL, NULL, 'Caudal del gas de protección (L/min), presión del gas en la línea (bar) y temperatura del gas (°C), según las funciones disponibles del modelo instalado.', 'FLOAT (Caudal del gas de protección en L/min) + FLOAT (Presión del gas en bar) + FLOAT (Temperatura del gas en °C).', 'Trama de datos digital mediante IO-Link hacia un maestro IO-Link, con posterior integración al PLC mediante el protocolo industrial utilizado por el sistema de control.', 'Detección de Falla: Detecta caídas o interrupciones anormales del caudal o presión del gas de protección, que pueden indicar una restricción, fuga o problema en el suministro. Predictivo: Analiza las tendencias de caudal y presión para identificar disminuciones progresivas que puedan indicar una obstrucción o deterioro del sistema de suministro de gas y requerir mantenimiento.', 'El software recibe los datos digitalizados del sensor y actualiza las variables (caudal_gas_lmin = 15.2 y presion_gas_bar = 4.2). Registra las mediciones durante cada ciclo de soldadura y compara sus valores y tendencias con los parámetros de referencia. El algoritmo aplica una condición (IF caudal_gas_lmin < limite_referencia THEN generar_alerta_flujo_gas()) para detectar una disminución anormal del suministro de gas que requiera inspección.', 1),
(23, 8, 2, 'EQ-CAR-08-S3', 'Transductor de corriente y voltaje del arco de alta velocidad', NULL, NULL, 'Voltaje eficaz del arco (V) y corriente de soldadura (A). La impedancia dinámica puede ser calculada por el sistema a partir de ambas variables.', 'FLOAT (Tensión de arco en V) + FLOAT (Corriente de soldadura en A).', 'Señales de voltaje y corriente de alta velocidad hacia un módulo de adquisición o controlador. Los datos digitalizados pueden integrarse mediante EtherCAT, PROFINET o EtherNet/IP, según la arquitectura del sistema de control.', 'Detección de Falla: Detecta picos o variaciones anormales de corriente y voltaje que pueden indicar un cortocircuito o inestabilidad del arco y generar una alarma o acción de protección. Predictivo: Analiza las tendencias y variaciones de corriente y voltaje para identificar cambios progresivos en la estabilidad del arco que puedan requerir inspección del sistema de soldadura.', 'El software recibe los datos digitalizados de corriente y voltaje, procesa los valores y actualiza las variables (voltaje_arco_v = 24.8 y corriente_arco_amp = 185.0). Registra las mediciones durante cada ciclo de soldadura y compara su comportamiento con los parámetros de referencia. El algoritmo analiza las variaciones de corriente y voltaje y puede aplicar una condición (IF desviacion_arco > limite_referencia THEN generar_alerta_inestabilidad_arco()) para detectar un comportamiento anormal que requiera inspección del sistema de soldadura.', 1),
(24, 9, NULL, 'EQ-CAR-09-S1', 'Sensor inteligente de posición para actuadores de giro y clamps', NULL, NULL, 'Ángulo de rotación del actuador o leva de sujeción (°) y posición del mecanismo. El contador de ciclos y la desviación respecto a la posición de referencia son valores calculados por el software, no mediciones directas del sensor.', 'FLOAT (Ángulo de giro del actuador en °) + FLOAT (Posición del mecanismo, según la resolución/interfaz del sensor).', 'Trama de datos digital mediante IO-Link hacia un maestro IO-Link, incluyendo el valor de posición y, según el modelo, información de diagnóstico del sensor.', 'Detección de Falla: Detecta recorridos incompletos o desviaciones anormales de la posición de cierre, que pueden indicar una obstrucción o anomalía en el mecanismo de sujeción. Predictivo: Analiza la tendencia de la posición y del recorrido de cierre para identificar desviaciones progresivas compatibles con desgaste o desajuste del mecanismo que requieran inspección y mantenimiento.', 'El software recibe la trama de datos digital del sensor, extrae el valor de posición y actualiza la variable (angulo_cierre_clamp = 90.4). Registra la posición alcanzada en cada ciclo y la compara con el valor de referencia. El algoritmo calcula la desviación de posición y puede aplicar una condición (IF desviacion_posicion > limite_referencia THEN generar_alerta_posicion_clamp()) para detectar un cambio anormal en el recorrido de cierre que requiera inspección del sistema de sujeción.', 1),
(25, 9, 3, 'EQ-CAR-09-S2', 'Sensor de presión electrónico compacto dual para actuadores', NULL, NULL, 'Presión estática del fluido de accionamiento en la cámara del actuador del clamp (bar).', 'FLOAT (Presión del actuador en bar).', 'Trama de datos digital mediante IO-Link hacia un maestro IO-Link, con transmisión del valor de presión y, según el modelo, información de diagnóstico del sensor.', 'Detección de Falla: Detecta una caída anormal de la presión del actuador durante la sujeción, que puede comprometer la fuerza de retención de la pieza y requerir una acción de protección. Predictivo: Analiza la tendencia de presión durante los ciclos de sujeción para identificar pérdidas progresivas respecto al comportamiento de referencia que puedan requerir inspección del actuador o del circuito neumático.', 'El software recibe el dato digital de presión y actualiza la variable (presion_clamp_bar = 5.4). Registra la presión durante cada ciclo de sujeción y compara su comportamiento con los valores de referencia. El algoritmo analiza las variaciones y puede aplicar una condición (IF presion_clamp_bar < limite_referencia THEN generar_alerta_presion_clamp()) para detectar una pérdida anormal de presión que requiera inspección del actuador o del circuito neumático.', 1),
(26, 9, 4, 'EQ-CAR-09-S3', 'Acelerómetro triaxial inteligente con procesamiento de señal integrado', NULL, NULL, 'Velocidad de vibración eficaz (RMS) en mm/s y aceleración pico en g, medidas independientemente en los ejes X, Y y Z, además de temperatura (°C).', 'FLOAT (Vibración RMS eje X) + FLOAT (Vibración RMS eje Y) + FLOAT (Vibración RMS eje Z) + FLOAT (Aceleración pico) + FLOAT (Temperatura en °C).', 'Trama de datos digital mediante IO-Link hacia un maestro IO-Link, con posterior integración al PLC mediante el protocolo industrial utilizado por el sistema de control.', 'Detección de Falla: Detecta incrementos anormales de aceleración o vibración durante el funcionamiento del clamp, que pueden indicar un impacto o comportamiento mecánico anormal y requerir una acción de protección. Predictivo: Analiza la tendencia de la vibración RMS y, cuando el sistema disponga de los datos necesarios, su contenido espectral para identificar cambios progresivos compatibles con holguras, desalineación o aflojamiento mecánico que requieran inspección.', 'El software recibe los datos digitalizados de vibración y actualiza los valores correspondientes (vibracion_rms_x = 1.2, vibracion_rms_y = 2.4 y vibracion_rms_z = 0.8). Registra cronológicamente el comportamiento vibratorio durante los ciclos de apertura y cierre y lo compara con la línea base de referencia. El algoritmo analiza las variaciones de vibración y puede aplicar una condición (IF vibracion_rms_y > limite_referencia THEN generar_alerta_vibracion_clamp()) para detectar un comportamiento mecánico anormal que requiera inspección del mecanismo de sujeción.', 1),
(27, 10, 4, 'EQ-CAR-10-S1', 'Acelerómetro triaxial inteligente de alta frecuencia', NULL, NULL, 'Velocidad de vibración eficaz (RMS) en mm/s, aceleración pico en g en los ejes X, Y y Z, y temperatura en el punto de medición (°C).', 'FLOAT (Vibración RMS eje X) + FLOAT (Vibración RMS eje Y) + FLOAT (Vibración RMS eje Z) + FLOAT (Aceleración pico en g) + FLOAT (Temperatura en el punto de medición en °C).', 'Trama de datos digital mediante IO-Link hacia un maestro IO-Link, con posterior integración al PLC mediante PROFINET, EtherNet/IP u otro protocolo industrial, según la arquitectura del sistema de control.', 'Detección de Falla: Detecta incrementos anormales de vibración, aceleración o temperatura durante el movimiento del robot, que pueden indicar una condición mecánica o térmica anormal que requiera una acción de protección. Predictivo: Analiza las tendencias de vibración y temperatura y, cuando se dispone de datos suficientes, el contenido espectral mediante FFT para identificar cambios progresivos compatibles con desgaste, holguras, desbalanceo u otras anomalías mecánicas que requieran inspección y mantenimiento.', 'El software recibe los datos digitalizados de vibración y temperatura y actualiza las variables (vibracion_robot_rms = 2.1 y temperatura_punto_medicion_c = 58.5). Registra cronológicamente las mediciones durante las trayectorias repetitivas del robot y compara su comportamiento con la línea base de referencia. El algoritmo analiza las tendencias y puede aplicar una condición (IF vibracion_robot_rms > limite_referencia THEN generar_alerta_vibracion_robot()) para detectar un incremento anormal de vibración que requiera inspección del eje o mecanismo correspondiente.', 1),
(28, 10, 2, 'EQ-CAR-10-S2', 'Sensor de corriente para motores/servomotores', NULL, NULL, 'Intensidad de corriente eléctrica instantánea consumida por las fases de potencia de los servomotores de los ejes principales (A).', 'FLOAT (Corriente eficaz RMS del servomotor en A).', 'Señal eléctrica proporcional a la corriente hacia el módulo de adquisición o drive, donde es digitalizada e integrada al sistema de control mediante un bus industrial como PROFINET, EtherCAT o EtherNet/IP, según la arquitectura del equipo.', 'Detección de Falla: Detecta incrementos anormales de corriente durante el movimiento del robot, que pueden indicar una sobrecarga, bloqueo mecánico o comportamiento anormal del accionamiento. Predictivo: Analiza la tendencia de corriente bajo rutinas de carga y velocidad equivalentes para identificar incrementos progresivos compatibles con un aumento de carga, fricción o deterioro mecánico que requieran inspección y mantenimiento.', 'El software recibe la señal de corriente digitalizada desde el módulo de adquisición o drive y actualiza la variable (corriente_servo_amp = 18.4). Registra cronológicamente el consumo de corriente durante cada trayectoria de manipulación y lo compara con el perfil de referencia del robot bajo condiciones equivalentes. El algoritmo analiza las variaciones de corriente y puede aplicar una condición (IF corriente_servo_amp > limite_referencia THEN generar_alerta_sobrecarga_servo()) para detectar un incremento anormal de carga que requiera inspección del eje o mecanismo correspondiente.', 1),
(29, 10, 1, 'EQ-CAR-10-S3', 'Sensor RTD Pt100 para temperatura de servomotores y reductores', NULL, NULL, 'Temperatura superficial de la carcasa del servomotor o del reductor en el punto de medición (°C).', 'FLOAT (Temperatura en °C).', 'Señal RTD Pt100 hacia un módulo de adquisición o transmisor de temperatura. El valor digitalizado puede integrarse al sistema de control mediante IO-Link o, mediante un transmisor, como señal analógica de 4–20 mA, según la arquitectura instalada.', 'Detección de Falla: Detecta incrementos anormales de temperatura en el servomotor o reductor que pueden indicar una condición térmica anormal o sobrecarga y requerir una acción de protección. Predictivo: Analiza la tendencia de temperatura durante ciclos de operación equivalentes para identificar incrementos progresivos compatibles con aumento de carga, fricción o deterioro térmico del sistema que requieran inspección y mantenimiento.', 'El software recibe el valor digitalizado de temperatura desde el módulo de adquisición o sistema de control y actualiza las variables (temperatura_motor_c = 68.5 y temperatura_reductor_c = 52.4). Registra cronológicamente la temperatura durante los ciclos de operación y la compara con la línea base térmica del robot bajo condiciones equivalentes. El algoritmo analiza la tendencia y puede aplicar una condición (IF temperatura_reductor_c > limite_referencia THEN generar_alerta_temperatura_reductor()) para detectar un incremento térmico anormal que requiera inspección del sistema de lubricación, del reductor o del accionamiento.', 1),
(30, 11, 4, 'EQ-PIN-11-S1', 'Sensor de vibración/aceleración del atomizador', NULL, NULL, 'Velocidad de vibración eficaz (RMS) en mm/s y aceleración pico en g en los ejes X, Y y Z del conjunto del atomizador.', 'FLOAT (Velocidad de vibración RMS en mm/s) + FLOAT (Aceleración pico en g).', 'Señal eléctrica del acelerómetro hacia un módulo de adquisición o controlador, donde se digitalizan los datos de vibración y aceleración para su integración con el sistema de control mediante la interfaz industrial disponible.', 'Detección de Falla: Detecta incrementos anormales de vibración o aceleración durante la rotación del atomizador, que pueden indicar un desequilibrio, impacto o comportamiento mecánico anormal que requiera una acción de protección. Predictivo: Analiza la tendencia de vibración durante ciclos de operación equivalentes para identificar incrementos progresivos compatibles con cambios en el equilibrio o deterioro del conjunto rotativo que requieran inspección y mantenimiento.', 'El software recibe los datos digitalizados de vibración y aceleración desde el módulo de adquisición y actualiza las variables (vibracion_cabezal_rms = 1.4 y aceleracion_pico_g = 2.1). Registra cronológicamente el comportamiento vibratorio durante cada ciclo de aplicación de pintura y lo compara con la línea base del atomizador bajo condiciones equivalentes. El algoritmo analiza las variaciones y puede aplicar una condición (IF vibracion_cabezal_rms > limite_referencia THEN generar_alerta_vibracion_atomizador()) para detectar un incremento anormal de vibración que requiera inspección del conjunto rotativo y del atomizador.', 1),
(31, 11, 3, 'EQ-PIN-11-S2', 'Sensor de presión del circuito de pintura', NULL, NULL, 'Presión del fluido de pintura en la línea de suministro hacia el cabezal (bar).', 'FLOAT (Presión del fluido de pintura en bar, obtenida después del escalado del valor de entrada).', 'Señal de salida del transmisor de presión hacia el módulo de adquisición o controlador, mediante IO-Link o señal analógica de 4–20 mA, según el modelo instalado y la arquitectura del sistema.', 'Detección de Falla: Detecta incrementos o caídas anormales de presión en la línea de suministro de pintura que pueden indicar una condición anormal del circuito y requerir una acción de protección. Predictivo: Analiza la tendencia de presión durante ciclos de aplicación equivalentes para identificar cambios progresivos compatibles con restricciones, variaciones del suministro o deterioro del sistema que requieran inspección y mantenimiento.', 'El software recibe el valor digitalizado de presión desde el módulo de adquisición o sistema de control y actualiza la variable (presion_circuito_pintura = 4.2). Registra cronológicamente el comportamiento de la presión durante cada ciclo de pintado y lo compara con la línea base establecida para condiciones de operación equivalentes. El algoritmo analiza las variaciones y puede aplicar una condición (IF presion_circuito_pintura > limite_referencia THEN generar_alerta_presion_circuito()) para detectar una desviación anormal de presión que requiera inspección del circuito de suministro de pintura.', 1),
(32, 11, NULL, 'EQ-PIN-11-S3', 'Sensor de temperatura del atomizador', NULL, NULL, 'Temperatura superficial de la carcasa del cuerpo del atomizador giratorio (°C).', 'FLOAT (Temperatura superficial del atomizador en °C).', 'Señal de salida del sensor hacia el módulo de adquisición o controlador, mediante Modbus RTU, IO-Link o una señal analógica, según el modelo instalado y la arquitectura del sistema.', 'Detección de Falla: Detecta incrementos anormales de temperatura en el cuerpo del atomizador que pueden indicar una condición térmica fuera de lo esperado y requerir una acción de protección. Predictivo: Analiza la tendencia de temperatura durante ciclos de operación equivalentes para identificar incrementos progresivos compatibles con cambios en las condiciones de operación o deterioro del conjunto que requieran inspección y mantenimiento.', 'El software recibe el valor digitalizado de temperatura desde el módulo de adquisición o sistema de control y actualiza la variable (temperatura_atomizador_c = 45.2). Registra cronológicamente el comportamiento térmico del atomizador durante los ciclos de aplicación y lo compara con la línea base establecida para condiciones de operación equivalentes. El algoritmo analiza la tendencia de temperatura y puede aplicar una condición (IF temperatura_atomizador_c > limite_referencia THEN generar_alerta_temperatura_atomizador()) para detectar un incremento térmico anormal que requiera inspección del atomizador y de sus componentes asociados.', 1),
(33, 12, 12, 'EQ-PIN-12-S1', 'Transductor de presión diferencial de alta precisión para aire y gases', NULL, NULL, 'Diferencia de presión entre el interior de la cabina y el ducto de extracción de aire (mbar).', 'INT16 (Valor de presión diferencial crudo; el PLC lo escala y convierte a FLOAT para obtener la presión diferencial en mbar).', 'Datos digitales mediante protocolo IO-Link desde el transductor hacia el maestro IO-Link, que posteriormente los integra al sistema de control mediante el protocolo industrial correspondiente.', 'Detección de Falla: Detecta una presión diferencial anormal que puede indicar una condición de ventilación fuera del rango esperado y requerir una acción de protección o inspección. Predictivo: Monitorea la tendencia de la presión diferencial durante condiciones de operación comparables para identificar un incremento progresivo compatible con aumento de resistencia del filtro y programar su inspección o reemplazo antes de afectar el flujo de aire.', 'El software recibe el valor digital de presión diferencial desde el maestro IO-Link, aplica el escalado correspondiente y actualiza la lectura (presion_diferencial_filtro_mbar = 12.4). Almacena cronológicamente los valores durante la operación de la ventilación y los compara con la línea base establecida para condiciones de operación equivalentes. El algoritmo analiza la tendencia de la presión diferencial y puede aplicar una condición (IF presion_diferencial_filtro_mbar > limite_referencia THEN generar_alerta_inspeccion_filtro()) para detectar un incremento anormal compatible con una mayor resistencia del sistema de filtrado y solicitar su inspección o reemplazo', 1),
(34, 12, 12, 'EQ-PIN-12-S2', 'Sensor de caudal y velocidad de aire (térmico/calorimétrico)', NULL, NULL, 'Caudal volumétrico del aire de extracción (m³/h), obtenido a partir de la medición de velocidad del flujo de aire (m/s) y las características de la sección de medición.', 'FLOAT (Caudal volumétrico actual de extracción de aire en m³/h', 'Datos digitales de proceso mediante protocolo IO-Link desde el sensor hacia el maestro IO-Link, que posteriormente los integra al sistema de control mediante el protocolo industrial correspondiente.', 'Detección de Falla: Detecta una disminución del caudal de extracción respecto al valor de referencia, indicando una condición anormal del sistema de ventilación que puede requerir una acción de protección. Predictivo: Analiza la tendencia del caudal bajo condiciones de operación comparables para identificar una disminución progresiva compatible con deterioro o restricción del sistema de extracción y solicitar su inspección antes de afectar las condiciones de ventilación.', 'El software recibe el valor digital de caudal desde el maestro IO-Link, aplica el escalado correspondiente y actualiza la lectura (caudal_extraccion_m3h = 1850.0). El sistema registra cronológicamente el caudal durante los ciclos de operación y lo compara con la línea base establecida para condiciones de ventilación equivalentes. El algoritmo analiza la tendencia del caudal y puede aplicar una condición (IF caudal_extraccion_m3h < limite_referencia THEN generar_alerta_caudal_extraccion()) para detectar una disminución anormal del flujo de extracción que requiera inspección del sistema de ventilación.', 1);
INSERT INTO `dispositivos_sensor` (`id_dispositivo`, `id_maquina`, `id_catalogo`, `codigo`, `nombre_sensor`, `marca_modelo`, `tipo_salida`, `variable_medida`, `tipo_dato_origen`, `formato_transmision`, `aplicacion_mantenimiento`, `lectura_software`, `activo`) VALUES
(35, 12, NULL, 'EQ-PIN-12-S3', 'Sensor de temperatura y humedad relativa del aire', NULL, NULL, 'Humedad relativa del aire (%) y temperatura del aire de la cabina (°C). El punto de rocío se calcula a partir de estas dos variables.', 'FLOAT (Humedad relativa del aire en %) + FLOAT (Temperatura del aire de la cabina en °C).', 'Datos digitales de proceso transmitidos cíclicamente mediante protocolo IO-Link desde el sensor hacia el maestro IO-Link, que posteriormente los integra al sistema de control mediante el protocolo industrial correspondiente.', 'Detección de Falla: Detecta condiciones anormales de temperatura o humedad que pueden afectar las condiciones de operación de la cabina y requerir una acción de protección. Predictivo: Analiza la tendencia de temperatura, humedad relativa y punto de rocío durante condiciones de operación comparables para identificar desviaciones progresivas de las condiciones ambientales y solicitar la inspección del sistema de climatización o deshumidificación.', 'El software recibe los datos digitales de humedad relativa y temperatura desde el maestro IO-Link y los convierte a sus unidades de ingeniería correspondientes (humedad_relativa_pct = 52.4 y temperatura_cabina_c = 22.5). A partir de estas variables obtiene el punto de rocío y registra cronológicamente las condiciones ambientales durante cada ciclo de producción. El algoritmo compara los valores con la línea base establecida para condiciones de operación equivalentes y puede aplicar una condición (IF humedad_relativa_pct > limite_humedad_referencia THEN generar_alerta_condicion_ambiental()) para detectar una desviación de las condiciones ambientales que requiera inspección del sistema de climatización o deshumidificación', 1),
(36, 13, 1, 'EQ-PIN-13-S1', 'Termocupla tipo K industrial', NULL, NULL, 'Temperatura del aire en cada zona de calentamiento del horno (°C).', 'INT16 (Valor de temperatura digitalizado; el módulo de adquisición o PLC lo escala para obtener el valor decimal FLOAT en °C).', 'Señal de la termocupla tipo K hacia un módulo de adquisición o transmisor de temperatura; el valor digitalizado puede integrarse al sistema mediante IO-Link, PROFINET u otra interfaz industrial, según el módulo utilizado.', 'Detección de Falla: Detecta temperaturas fuera del rango de operación establecido en las diferentes zonas del horno, permitiendo generar una alerta o activar una acción de protección definida por el sistema de control. Predictivo: Analiza la tendencia y velocidad de variación de la temperatura durante ciclos equivalentes para identificar desviaciones progresivas del comportamiento térmico que requieran inspección del sistema de calentamiento.', 'El software recibe la señal digitalizada de temperatura desde el módulo de adquisición o sistema de control y actualiza la lectura (temperatura_horno_c = 180.5). El sistema registra cronológicamente la temperatura de cada zona durante los ciclos de operación y la compara con la línea base establecida para condiciones de operación equivalentes. El algoritmo analiza la temperatura y su velocidad de variación y puede aplicar una condición (IF temperatura_horno_c < limite_referencia THEN generar_alerta_desviacion_termica()) para detectar una desviación del comportamiento térmico esperado que requiera inspección del sistema de calentamiento', 1),
(37, 13, 12, 'EQ-PIN-13-S2', 'Sensor de presión diferencial del sistema de extracción', NULL, NULL, 'Diferencia de presión entre la cámara interna del horno y el ducto de evacuación de gases (Pa).', 'INT16 (Valor de presión diferencial crudo; el PLC aplica el factor de escala para convertirlo a un valor FLOAT en Pa).', 'Datos digitales de proceso transmitidos cíclicamente mediante IO-Link desde el sensor hacia el maestro IO-Link, que posteriormente los integra al PLC mediante la interfaz industrial correspondiente.', 'Detección de Falla: Detecta una presión diferencial fuera del rango establecido para el sistema de extracción, permitiendo generar una alerta o activar un interbloqueo de seguridad cuando las condiciones de ventilación no sean adecuadas. Predictivo: Analiza la tendencia de la presión diferencial durante la operación para identificar cambios progresivos compatibles con un aumento de resistencia u obstrucción del sistema de extracción, indicando la necesidad de inspección y mantenimiento.', 'El software recibe el valor digital de presión diferencial desde el maestro IO-Link, aplica el escalado correspondiente y actualiza la lectura (presion_dif_extraccion_pa = 860.0). El sistema almacena cronológicamente los valores durante la operación del horno y los compara con una línea base establecida para condiciones de operación equivalentes. El algoritmo analiza la tendencia de la presión diferencial y puede aplicar una condición (IF presion_dif_extraccion_pa > limite_referencia THEN generar_alerta_inspeccion_extraccion()) para detectar un incremento anormal compatible con una mayor resistencia del sistema de extracción y solicitar su inspección.', 1),
(38, 13, 4, 'EQ-PIN-13-S3', 'Sensor de vibración del ventilador de extracción', NULL, NULL, 'Velocidad de vibración eficaz (v-RMS en mm/s), aceleración pico (a-Peak en g) y temperatura superficial del componente no giratorio en el punto de medición (°C).', 'INT16 (Vibración RMS en mm/s) + INT16 (Aceleración pico en g) + INT16 (Temperatura en °C', 'Datos digitales de proceso transmitidos cíclicamente mediante IO-Link desde el sensor hacia el maestro IO-Link, que posteriormente los integra al PLC mediante la interfaz industrial correspondiente.', 'Detección de Falla: Detecta incrementos anormales de vibración, aceleración o temperatura que pueden indicar una condición mecánica anormal del extractor y requerir una acción de protección o inspección. Predictivo: Analiza la tendencia de la vibración y, cuando se dispone de datos adecuados, su comportamiento espectral para identificar cambios progresivos compatibles con desbalance, desalineación, holguras o deterioro de rodamientos, permitiendo programar su inspección y mantenimiento.', 'El software recibe los datos digitales de vibración y temperatura desde el maestro IO-Link y actualiza las lecturas correspondientes (vibracion_extractor_rms = 3.4 y temperatura_superficial_c = 72.0). El sistema almacena cronológicamente los valores durante la operación del horno y los compara con una línea base y los criterios de evaluación de vibración establecidos para el equipo. El algoritmo analiza la tendencia de la vibración y, cuando dispone de datos adecuados para análisis espectral, puede utilizar FFT para identificar cambios en las frecuencias dominantes. Una condición como (IF vibracion_extractor_rms > limite_referencia THEN generar_alerta_inspeccion_extractor()) permite detectar un incremento anormal de vibración y solicitar la inspección del conjunto ro', 1),
(39, 14, 7, 'EQ-ENS-14-S1', 'Sensor de fuerza/torque multi-eje en la muñeca (FT 6-DOF)', NULL, NULL, 'Fuerza de contacto y par de torsión ejercido en las 6 direcciones del espacio (Fx, Fy, Fz en Newtons N y Mx, My, Mz en N⋅m).', 'FLOAT (Fuerza en N por eje) + FLOAT (Torque en N⋅m por eje) + BOOL (colision_detectada = True/False).', 'Comunicación digital de ultra alta velocidad vía EtherCAT / PROFINET IRT a 1 kHz directa al controlador del robot.', 'Prevención: Previene el doblamiento o ruptura de la herramienta de agarre (EOAT), deformación de componentes por sobrepresión y colisiones destructivas contra la estructura. Detección de Falla: Detecta piezas trabadas, orificios mal alineados durante la inserción o sobreesfuerzo en los servomotores del robot.', 'El software de control del robot (o PLC) monitorea la fuerza de inserción en tiempo real. Si la fuerza en el eje Z supera el límite configurado (ej. Fz > 25.0 N) durante el encaje, detiene la trayectoria en milisegundos, activa la bandera colision_detectada = True y retrocede 10 mm automáticamente para liberar la pieza.', 1),
(40, 14, 5, 'EQ-ENS-14-S2', 'Encoders absolutos de posición y corriente de servomotores', NULL, NULL, 'Posición angular exacta de cada eje (grados °), velocidad de rotación (RPM) y consumo de corriente del motor (Amperios A).', 'FLOAT (Ángulo en grados por articulación J1-J6) + FLOAT (Corriente A por motor) + UINT16 (Código de error)', 'Bus de campo industrial integrado del fabricante (ej. DRIVE-CLiQ / Ethernet de seguridad) hacia la unidad de control del robot.', 'Prevención: Evita el sobrecalentamiento y la quemadura de los devanados del motor por resistencia mecánica excesiva. Detección de Falla: Identifica desgaste en reductores armónicos (holguras/backlash), falta de grasa en articulaciones o desincronización en el eje de movimiento.', 'El software analiza la curva de consumo de corriente en cada articulación. Si la corriente de la articulación 3 se eleva un 30% por encima de su perfil nominal histórico sin incremento de carga, el sistema genera una alerta predictiva de MANTENIMIENTO_REDUCTOR_REQUERIDO y limita la aceleración del robot para evitar un fallo catastrófico.', 1),
(41, 15, 10, 'EQ-ENS-15-S1', 'Transductor integrado de torque rotativo y ángulo de apriete', NULL, NULL, 'Par de apriete aplicado (medido en Newton-metro N⋅m / cN⋅m) y ángulo de rotación de la rosca (grados °).', 'FLOAT (Torque alcanzado N⋅m) + FLOAT (Ángulo alcanzado °) + BYTE (Estatus: 0x01 = OK / 0x02 = NOK / 0x03 = TRASROSCADO).', 'Galgas extensiométricas piezoeléctricas dinámicas con transmisión digital vía PROFINET IRT / EtherCAT directas al controlador del husillo.', 'Prevención: Previene la fractura del perno por sobreapriete, barrido de cuerdas en la pieza de trabajo o fisuras en componentes plásticos/metálicos. Detección de Falla: Identifica tornillos cruzados (rosca trasroscada), pernos faltantes, cuerda sucia o longitud incorrecta de tornillo.', 'El software procesa en tiempo real la curva de Torque vs. Ángulo durante el ciclo. Si el torque pico supera el límite superior (ej. Torque > 12.5 N⋅m) o alcanza el torque antes del ángulo mínimo (rosca cruzada), aborta el giro en milisegundos, asigna estatus = NOK, enciende la luz roja de la estación y bloquea el avance de la pieza.', 1),
(42, 15, 9, 'EQ-ENS-15-S2', 'Sensor de carrera/profundidad y presencia de tornillo (LVDT/óptico)', NULL, NULL, 'Desplazamiento lineal del husillo / profundidad de asentamiento (mm) y presencia física del tornillo en la boquilla', 'FLOAT (Profundidad de inserción mm) + BOOL (tornillo_presente = True/False) + BOOL (asentamiento_correcto).', 'Señal analógica de LVDT (0-10 V DC) o entrada digital discreta (24V DC PNP) hacia el PLC de la celda.', 'Prevención: Evita que el cabezal del atornillador colisione directamente contra la pieza sin haber recibido un tornillo, protegiendo la punta (bit) y el husillo. Detección de Falla: Detecta atascamientos de tornillos en el alimentador de tazón, tornillos dobles o aprietes incompletos por falta de carrer', 'El software verifica antes de cada ciclo si tornillo_presente == True. Si es True, inicia el avance del husillo y valida la profundidad final: Si profundidad_mm < limite_minimo_asentamiento (ej. 18.0 mm), el sistema marca la junta como incompletamente atornillada y activa la secuencia de retención automática de la pieza.', 1),
(43, 16, 7, 'EQ-ENS-16-S1', 'Celda de carga piezoeléctrica / transductor de fuerza de inserción', NULL, NULL, 'Fuerza de compresión y empuje ejercida por el vástago/pistón sobre la pieza (medido en Kilonewtons kN o Newtons N).', 'FLOAT (Fuerza instantánea en kN) + FLOAT (Fuerza pico alcanzada en kN) + BOOL (fuerza_excesiva = True/False)', 'Señal de milivoltios de galga extensible amplificada a 0-10 V DC / comunicación rápida PROFINET IRT / EtherCAT.', 'Prevención: Previene la fractura del troquel/matriz, deformación permanente de la carcasa, aplastamiento de componentes o rupturas por sobrepresión. Detección de Falla: Identifica componentes fuera de tolerancia dimensional (piezas demasiado grandes), interferencias mecánicas por falta de lubricación o atascos.', 'El software evalúa la fuerza ejercida continuamente durante la carrera. Si fuerza_kN > limite_max_seguridad (ej. 15.0 kN), detiene inmediatamente el servomotor/cilindro neumático en menos de 10 ms, ejecuta un retroceso automático (Back-off) de 20 mm para liberar la pieza y emite la alarma SOBRECARGA_PRENSA_NOK.', 1),
(44, 16, 9, 'EQ-ENS-16-S2', 'Regla optoelectrónica / sensor de desplazamiento lineal (LVDT/encoder)', NULL, NULL, 'Posición lineal continua y profundidad de asentamiento del vástago de la prensa (medido en milímetros mm o micrómetros µm).', 'FLOAT (Posición actual en mm) + FLOAT (Profundidad final de inserción en mm) + ARRAY (Curva Fuerza vs. Desplazamiento)', 'Señal digital codificada vía SSI (Synchronous Serial Interface) / BiSS-C o entrada analógica de alta resolución (0-10 V DC).', 'Prevención: Evita impactos secos del ariete contra la base fijadora en carreras en vacío y previene inserciones incompletas. Detección de Falla: Detecta ausencia de componentes (pieza faltante en el troquel), asientos de baleros mal mecanizados o deformación elástica de la estructura.', 'El software evalúa la curva característica de Fuerza vs. Desplazamiento (Ventanas de Evaluación / Windows). Si la posición final posicion_mm no alcanza la tolerancia requerida (ej. profundidad_final < 45.2 mm) al llegar al límite de fuerza, el sistema marca el ensamble como INSERCION_INCOMPLETA_NOK, bloquea la expulsión de la pieza y registra la gráfica del fallo.', 1),
(45, 17, 11, 'EQ-MOT-17-S1', 'Sistema de visión artificial 3D / cámara guiada por IA', NULL, NULL, 'Desviación espacial y coordenadas tridimensionales (X,Y,Z) de los puntos de montaje.', 'FLOAT (Desviación en milímetros para X,Y,Z) + BOOL (posicion_correcta).', 'Matriz de datos de imagen transmitida a alta velocidad vía GigE Vision / Ethernet Industrial (1 Gbps).', 'Prevención: Evita que el elevador neumático golpee o deforme la estructura de la carrocería si el chasis llegó mal colgado o desplazado. Detección de Falla: Detecta orificios obstruidos, soportes torcidos o ausencia de bujes de goma antes de iniciar la elevación.', NULL, 1),
(46, 17, 10, 'EQ-MOT-17-S2', 'Transductor de torque y ángulo de atornillado (multihusillo servocontrolado)', NULL, NULL, 'Par de apriete (N⋅m) y ángulo de rotación (grados °).', 'FLOAT (Torque real en N⋅m) + FLOAT (Ángulo alcanzado) + BYTE (Status de apriete 0x01 = OK, 0x02 = NOK).', 'Galgas extensiométricas piezoeléctricas (0-10V DC) a través de bus PROFINET / EtherCAT.', 'Prevención: Evita fracturar los roscados del bloque de motor o romper el perno por sobreapriete. Detección de Falla: Identifica pernos cruzados (rosca trasroscada), tornillos faltantes o pernos defectuosos que no alcanzaron el torque mínimo de seguridad.', 'El software procesa la curva de torque vs. ángulo en tiempo real. Si torque_final < 120 Nm o el ángulo se dispara antes de tiempo (rosca_trasroscada == True), marca la pieza como NOK, enciende luz roja en la estación y rechaza el vehículo..', 1),
(47, 17, 7, 'EQ-MOT-17-S3', 'Celda de carga y sensor de presión de inserción (eje Z)', NULL, NULL, 'Fuerza de empuje o resistencia mecánica vertical (Newton / kilonewton).', 'FLOAT (Fuerza ejercida en kN) o UINT16 (Valor de entrada analógica de 0 a 65535).', 'Lazo de corriente analógico (4-20 mA) convertido a protocolo digital en el PLC.', 'Prevención: Si un cable, manguera o tubería del motor queda atrapada durante la elevación, el sensor detecta un pico repentino de fuerza y detiene la prensa antes de aplastar o romper componentes. Detección de Falla: Detección de interferencias mecánicas o atascamientos en las guías de ensamblaje.', 'El software monitorea el perfil de fuerza en la subida: IF fuerza_medida_kN > limite_maximo_seguridad (e.j. 5.0 kN), detiene el servomotor en milisegundos y retrocede el elevador 50 mm automáticamente (Back-off) para evitar aplastamientos.', 1),
(48, 18, 4, 'EQ-MOT-18-S1', 'Sensor de vibración del eje (nombre no indicado en el Excel)', NULL, NULL, 'Aceleración armónica y amplitud de vibración en el eje (g / m/s²).', 'FLOAT (Aceleración) y ARRAY (Análisis de Espectro FFT en frecuencia).', 'Voltaje de alta frecuencia (0-10V) transmitido vía EtherCAT a 10 kHz.', 'Detección de Falla: Detecta micro-fisuras, rodamientos astillados o engranajes mal acoplados. Prevención de Daño: Si la amplitud supera los 3.5g, desacopla inmediatamente el dinamómetro para evitar que el motor explote o se desintegre físicamente por resonancia.', 'El software calcula la transformada rápida de Fourier (FFT): IF aceleracion_g > 3.5 OR pico_armonico == TRUE, aborta la prueba, activa la interrupción de emergencia EMERGENCY_SHUTDOWN y registra el espectro de la falla.', 1),
(49, 18, 10, 'EQ-MOT-18-S2', 'Transductor torsional de alta velocidad (torque y sobrecarga)', NULL, NULL, 'Par torsor rotacional (N⋅m) y velocidad angular (RPM).', 'FLOAT (Torque en N⋅m) + UINT16 (Velocidad en RPM).', 'Puente de galgas extensiométricas inalámbrico / Telemetría digital PROFINET IRT.', 'Detección de Falla: Atascamiento mecánico o traba del diferencial/transmisión. Prevención de Daño: Corta la energía del dinamómetro en menos de 5 ms antes de que la torsión alcance el límite de ruptura del material (Yield Strength).', 'El software evalúa la derivada del torque respecto al tiempo (dT/dt): IF torque_nm > limite_max_seguridad (e.j. 450.0 Nm), limita instantáneamente la corriente del estátor y aplica el freno regenerativo de absorción.', 1),
(50, 18, NULL, 'EQ-MOT-18-S3', 'Sensor térmico infrarrojo de matriz óptica / termopar integrado', NULL, NULL, 'Temperatura superficial puntual y gradiente térmico de la carcasa (°C).', 'FLOAT (Temperatura en grados Celsius, ej. 115.4 °C).', 'Comunicación digital de alta velocidad por Modbus TCP o protocolo CANopen.', 'Detección de Falla: Fugas en el sistema de enfriamiento o fricción seca por ausencia de aceite/lubricante. Prevención de Daño: Previene la deformación térmica de la culata/carcasa y el incendio de fluidos al detener el motor antes de alcanzar el punto crítico de fusión.', 'El software monitorea el valor continuo: IF temperatura_c > 110.0 °C, activa el sistema de enfriamiento auxiliar al 100%. Si temperatura_c > 125.0 °C, ordena el apagado controlado (Safe Idle Drop) y bloquea el reinicio del banco hasta la inspección técnica.', 1),
(51, 19, 11, 'EQ-MOT-19-S1', 'Cámara de visión matricial 2D/3D con iluminación estroboscópica LED', NULL, NULL, 'Profundidad, espesor, rugosidad y volumen del cordón de soldadura/adhesivo (/ mm).', 'FLOAT (Espesor/Ancho en mm) + ARRAY (Perfil de elevación 3D) + BYTE (Estado_Sello).', 'Señal de disparo digital + Datos vía PROFINET IRT / EtherCAT o Ethernet TCP/IP.', 'Prevención: Previene fugas de fluidos en los ensambles al asegurar la continuidad del sellado de adhesivo. Detección de Falla: Detecta interrupciones en el cordón de goma, variaciones de espesor o burbujas de aire.', 'El software analiza el perfil de altura en continuo. Si espesor_cordon_mm < limite_min_1.5mm, el algoritmo de control genera la alerta CORDO_INCOMPLETO, detiene el avance de la cinta transportadora y registra las coordenadas de xy y para efectos de auditoria.', 1),
(52, 19, NULL, 'EQ-MOT-19-S2', 'Sensor láser profilómetro triangulado 3D (escáner de perfil)', NULL, NULL, 'Profundidad, espesor, rugosidad y volumen del cordón de soldadura o adhesivo (medido en micrómetros µm y milímetros mm).', 'FLOAT (Espesor y ancho en mm) + ARRAY (Perfil de elevación 3D) + BYTE (Estado del sello).', 'Señal de disparo digital de pulso + Transmisión de datos vía PROFINET IRT / EtherCAT o Ethernet TCP/IP.', 'Prevención: Previene fugas de fluidos en los ensambles al asegurar la continuidad del cordón de adhesivo. Detección de Falla: Detecta interrupciones en el cordón de goma, variaciones de espesor o presencia de burbujas de aire.', 'El software analiza el perfil de altura en continuo. Si espesor_cordon_mm < limite_min_1.5mm, el algoritmo de control genera la alerta CORTE_DE_CORDO_INCOMPLETO, detiene el avance de la cinta transportadora y registra las coordenadas (X,Y) del defecto para auditoría.', 1),
(53, 19, NULL, 'EQ-MOT-19-S3', 'Pirómetro infrarrojo de matriz térmica (cámara termográfica)', NULL, NULL, 'Temperatura superficial puntual y mapa de gradiente térmico del componente (medido en grados Celsius °C).', 'FLOAT (Temperatura máxima en °C) + BOOL (sobrecalentamiento = True/False).', 'Señal analógica de 4-20 mA o protocolo digital Modbus TCP / CANopen.', 'Prevención: Evita incendios, deformaciones térmicas o fallas de curado al detectar sobrecalentamientos en placas o piezas recién soldadas. Detección de Falla: Detecta cortocircuitos en tarjetas electrónicas, componentes sobrecalentados o curado térmico insuficiente en resinas', 'El software recibe la matriz de temperatura en tiempo real. Si temp_max_C > 85.0 °C, activa el sistema de enfriamiento auxiliar por aire, marca el elemento como NOK_TERMICO e interrumpe la secuencia de empaque automatizado.', 1),
(54, 20, 7, 'EQ-MOT-20-S1', 'Celda de carga / sensor de esfuerzo de frenado y tracción en rodillos', NULL, NULL, 'Fuerza de tracción y par de frenado dinámico ejercido por las ruedas sobre el rodillo (medido en Kilonewtons kN y Newton-metro N⋅m', 'FLOAT (Fuerza de tracción/freno en kN) + FLOAT (Desbalanceo de frenado %) + BOOL (prueba_freno_aprobada).', 'Puente de galgas extensiométricas analógico (0-10 V DC) convertido a protocolo PROFINET IRT / EtherCAT.', 'Prevención: Evita el sobrecalentamiento destructivo de los frenos o el reventón de llantas por amarre mecánico en el rodillo. Detección de Falla: Identifica desequilibrios en el reparto de frenado entre ejes (freno defectuoso) o deslizamiento de la transmisión.', 'El software evalúa la fuerza de frenado en tiempo real. Si la diferencia de fuerza entre la rueda izquierda y derecha supera el 20% (desbalanceo) o la fuerza de frenado no alcanza los kN mínimos de seguridad, asigna prueba_freno_aprobada = False, aplica el freno de emergencia del rodillo y enciende la alerta de falla.', 1),
(55, 20, 4, 'EQ-MOT-20-S2', 'Acelerómetro triaxial de vibración y desalineación (NVH en chasis)', NULL, NULL, 'Amplitud de vibración armónica y aceleración tridimensional en los ejes X, Y, Z (medido en g / m/s² y frecuencia en Hz).', 'FLOAT (Aceleración de vibración en g) + ARRAY (Espectro de frecuencia FFT) + BOOL (vibracion_anormal).', 'Señal piezoeléctrica de alta frecuencia transmitida por bus EtherCAT a 10 kHz o Ethernet TCP/IP.', 'Prevención: Previene la ruptura de ejes, desacoplamientos violentos del vehículo del banco o daños mecánicos en el motor por resonancia. Detección de Falla: Detecta rines deformados, llantas desbalanceadas, flechas/homocinéticas defectuosas o rodamientos dañados.', 'El software procesa la FFT (Transformada Rápida de Fourier) de la vibración durante la aceleración en rodillos. Si la aceleración supera los 2.5g en cualquier eje, el sistema aborta automáticamente la prueba de velocidad, desacopla los rodillos del dinamómetro y emite la alarma VIBRACION_CRITICA_CHASIS', 1);
