--
-- Disparadores `lecturas`
--
DELIMITER $$
CREATE TRIGGER `trg_lectura_alerta` AFTER INSERT ON `lecturas` FOR EACH ROW BEGIN
  DECLARE v_min DECIMAL(12,4);
  DECLARE v_max DECIMAL(12,4);
  SELECT umbral_min, umbral_max INTO v_min, v_max FROM sensores WHERE id_sensor = NEW.id_sensor;
  
  IF v_max IS NOT NULL AND NEW.valor > v_max THEN
    VALUES (NEW.id_sensor, NEW.id_lectura, 'sobre_maximo', NEW.valor, NEW.fecha_hora);
  ELSEIF v_min IS NOT NULL AND NEW.valor < v_min THEN
    VALUES (NEW.id_sensor, NEW.id_lectura, 'bajo_minimo', NEW.valor, NEW.fecha_hora);
  END IF;
END
$$
DELIMITER ;

