DROP TABLE IF EXISTS `vista_alertas_pendientes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_alertas_pendientes`  AS SELECT `al`.`id_alerta` AS `id_alerta`, `a`.`nombre_area` AS `area`, `m`.`codigo` AS `maquina`, coalesce(`s`.`nombre_variable`,`ts`.`nom_sensor`) AS `variable`, `al`.`tipo` AS `tipo`, `al`.`valor` AS `valor`, `ts`.`unidad_medida` AS `unidad_medida`, `al`.`fecha_hora` AS `fecha_hora`, `s`.`codigo` AS `sensor` FROM ((((`alertas` `al` join `sensores` `s` on(`s`.`id_sensor` = `al`.`id_sensor`)) join `maquinas` `m` on(`m`.`id_maquina` = `s`.`id_maquina`)) join `areas` `a` on(`a`.`id_area` = `m`.`id_area`)) join `tipos_sensor` `ts` on(`ts`.`id_tipo_sensor` = `s`.`id_tipo_sensor`)) WHERE `al`.`atendida` = 0 ORDER BY `al`.`fecha_hora` DESC ;

