CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_ultima_lectura`  AS SELECT `m`.`id_maquina` AS `id_maquina`, `m`.`codigo` AS `maquina`, `a`.`nombre_area` AS `area`, coalesce(`s`.`nombre_variable`,`ts`.`nom_sensor`) AS `variable`, `ts`.`unidad_medida` AS `unidad_medida`, `l`.`valor` AS `valor`, `l`.`fecha_hora` AS `fecha_hora`, `s`.`id_sensor` AS `id_sensor`, `s`.`codigo` AS `sensor` FROM ((((`sensores` `s` join `maquinas` `m` on(`m`.`id_maquina` = `s`.`id_maquina`)) join `areas` `a` on(`a`.`id_area` = `m`.`id_area`)) join `tipos_sensor` `ts` on(`ts`.`id_tipo_sensor` = `s`.`id_tipo_sensor`)) join `lecturas` `l` on(`l`.`id_lectura` = (select max(`lecturas`.`id_lectura`) from `lecturas` where `lecturas`.`id_sensor` = `s`.`id_sensor`))) ;

